def search_algorithm(src, dsts, G, num_partitions):
    """Build a low-cost shared broadcast tree, then assign its route to every partition.

    The algorithm compares independent shortest paths with shared-relay trees and
    a greedy marginal-cost expansion.  Edge costs already present in a candidate
    tree have zero marginal cost, encouraging one transfer to be reused by
    multiple destination branches rather than repeatedly paying for identical
    network links.
    """
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    def edge_cost(u, v):
        value = h[u][v].get("cost")
        return float("inf") if value is None else float(value)

    def tree_cost(edges):
        return sum(edge_cost(u, v) for u, v in edges)

    def paths_to_edges(paths):
        return {
            (path[i], path[i + 1])
            for path in paths.values()
            for i in range(len(path) - 1)
        }

    # Baseline: cheapest route for each destination independently.
    shortest_paths = {
        dst: nx.dijkstra_path(h, src, dst, weight="cost")
        for dst in dsts
    }
    best_edges = paths_to_edges(shortest_paths)

    # A relay can make an otherwise slightly longer route much cheaper when the
    # source-to-relay segment is shared by many destinations.
    for relay in h.nodes:
        try:
            relay_path = nx.dijkstra_path(h, src, relay, weight="cost")
            relay_paths = {
                dst: nx.dijkstra_path(h, relay, dst, weight="cost")
                for dst in dsts
            }
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            continue

        candidate_edges = paths_to_edges(relay_paths)
        candidate_edges.update(
            (relay_path[i], relay_path[i + 1])
            for i in range(len(relay_path) - 1)
        )
        if tree_cost(candidate_edges) < tree_cost(best_edges):
            best_edges = candidate_edges

    # Grow a tree by repeatedly adding the destination with the cheapest
    # marginal connection. Existing tree links are free in this calculation.
    greedy_edges = set()
    connected_nodes = {src}
    remaining = set(dsts)

    while remaining:
        def marginal_weight(u, v, data):
            return 0.0 if (u, v) in greedy_edges else edge_cost(u, v)

        lengths, marginal_paths = nx.multi_source_dijkstra(
            h, connected_nodes, weight=marginal_weight
        )
        reachable = [dst for dst in remaining if dst in lengths]
        if not reachable:
            break

        dst = min(reachable, key=lambda node: lengths[node])
        path = marginal_paths[dst]
        greedy_edges.update(
            (path[i], path[i + 1]) for i in range(len(path) - 1)
        )
        connected_nodes.update(path)
        remaining.remove(dst)

    if not remaining and tree_cost(greedy_edges) < tree_cost(best_edges):
