    """Return a minimum shared-edge broadcast tree.

    Small fan-outs use exact directed-Steiner dynamic programming. Larger
    fan-outs evaluate several relay-growth orders with zero marginal cost for
    already broadcast edges, selecting the cheapest feasible shared tree.
    """
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    h.remove_edges_from([
        (u, v) for u, v, data in h.edges(data=True)
        if data.get("cost") is None
    ])

    topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = list(dict.fromkeys(dsts))

    def emit(paths):
        for dst, path in paths.items():
            for u, v in zip(path, path[1:]):
                for partition in range(num_partitions):
                    topology.append_dst_partition_path(
                        dst, partition, [u, v, G[u][v]]
                    )
        return topology

    if not terminals:
        return topology

    # Exact optimization is exponential in destination count, rather than
    # region count. Wide broadcasts use a scalable shared-edge heuristic.
    if len(terminals) > 13:
        independent = {
            dst: nx.dijkstra_path(h, src, dst, weight="cost")
            for dst in terminals
        }
        independent_edges = {
            (u, v)
            for path in independent.values()
            for u, v in zip(path, path[1:])
        }
        order = {dst: i for i, dst in enumerate(terminals)}

        def edge_total(edges):
            return sum(float(h[u][v]["cost"]) for u, v in edges)

        def grow(first=None):
            """Grow a shared tree, optionally forcing its first relay target."""
            selected = set()
            connected = {src}
            remaining = set(terminals)

            if first is not None:
                path = independent[first]
                selected.update(zip(path, path[1:]))
                connected.update(path)
                remaining.discard(first)

            while remaining:
                def marginal_cost(u, v, data):
                    return 0.0 if (u, v) in selected else float(data["cost"])

                lengths, routes = nx.multi_source_dijkstra(
                    h, connected, weight=marginal_cost
                )
                reachable = [dst for dst in remaining if dst in lengths]
                if not reachable:
                    return None

                # A route can pass through other destinations; choosing the
                # earliest such route allows them to become zero-cost joins.
                dst = min(reachable, key=lambda node: (lengths[node], order[node]))
                path = routes[dst]
                selected.update(zip(path, path[1:]))
                connected.update(path)
                remaining.difference_update(set(path) & remaining)

            return selected

        # The unforced candidate is the old greedy behavior.  Trying each
        # destination as the first branch avoids its order-dependent local
        # minimum while remaining practical only in the scalable fallback.
        best_edges = independent_edges
        best_cost = edge_total(best_edges)
        for first in [None] + terminals:
            candidate = grow(first)
            if candidate is not None:
                candidate_cost = edge_total(candidate)
                if candidate_cost < best_cost:
                    best_edges, best_cost = candidate, candidate_cost

        tree = nx.DiGraph()
        tree.add_edges_from(best_edges)
        return emit({
            dst: nx.shortest_path(tree, src, dst)
            for dst in terminals
        })

    nodes = list(h.nodes)
    index = {node: i for i, node in enumerate(nodes)}
    n = len(nodes)
    mask_count = 1 << len(terminals)
    inf = float("inf")
    dp = [[inf] * n for _ in range(mask_count)]
    choice = [[None] * n for _ in range(mask_count)]
    reverse = h.reverse(copy=False)

    # dp[mask][node] is the cheapest tree rooted at node that reaches every
    # destination represented in mask. Join trees, then relax roots backwards.
    import heapq
    for mask in range(1, mask_count):
        if mask & (mask - 1) == 0:
            terminal = terminals[mask.bit_length() - 1]
            dp[mask][index[terminal]] = 0.0
        else:
            submask = (mask - 1) & mask
            while submask:
                other = mask ^ submask
                if other and submask < other:
                    for i in range(n):
                        candidate = dp[submask][i] + dp[other][i]
                        if candidate < dp[mask][i]:
                            dp[mask][i] = candidate
                            choice[mask][i] = ("split", submask, other)
                submask = (submask - 1) & mask

        heap = [
            (dp[mask][i], nodes[i])
            for i in range(n)
            if dp[mask][i] < inf
        ]
        heapq.heapify(heap)

        while heap:
            cost, child = heapq.heappop(heap)
            child_index = index[child]
            if cost != dp[mask][child_index]:
                continue

            for parent in reverse.neighbors(child):
                parent_index = index[parent]
                candidate = cost + float(h[parent][child]["cost"])
                if candidate < dp[mask][parent_index]:
                    dp[mask][parent_index] = candidate
                    choice[mask][parent_index] = ("edge", child)
                    heapq.heappush(heap, (candidate, parent))

    selected = set()

    def recover(mask, node):
        step = choice[mask][index[node]]
        if step is None:
            return
        if step[0] == "split":
            recover(step[1], node)
            recover(step[2], node)
        else:
            child = step[1]
            selected.add((node, child))
            recover(mask, child)

    recover(mask_count - 1, src)

    # Recovery may contain equivalent branches that are not required by any
    # receiver. Remove expensive redundant links before choosing emitted paths.
    tree = nx.DiGraph()
    tree.add_edges_from(selected)
    for u, v in sorted(
        list(tree.edges()),
        key=lambda edge: float(h[edge[0]][edge[1]]["cost"]),
        reverse=True,
    ):
        tree.remove_edge(u, v)
        if not all(nx.has_path(tree, src, dst) for dst in terminals):
            tree.add_edge(u, v)

    shared_paths = {}
    for dst in terminals:
        try:
            # Cost-weighted extraction avoids choosing an arbitrary hop-minimal
            # route when the recovered directed structure has multiple routes.
            shared_paths[dst] = nx.dijkstra_path(tree, src, dst, weight=lambda u, v, data: float(h[u][v]["cost"]))
        except nx.NetworkXNoPath:
            shared_paths[dst] = nx.dijkstra_path(h, src, dst, weight="cost")

    independent_paths = {
        dst: nx.dijkstra_path(h, src, dst, weight="cost")
        for dst in terminals
    }

    def emitted_cost(paths):
        """Return one-time cost of the distinct links used by emitted routes."""
        edges = {
            (u, v)
            for path in paths.values()
            for u, v in zip(path, path[1:])
        }
        return sum(float(h[u][v]["cost"]) for u, v in edges)

    # The DP is normally superior, but this safeguard accounts for recovery
    # ties and ensures the returned topology is never worse than direct
    # independently cheapest routes under the shared-edge cost model.
    return emit(
        shared_paths
        if emitted_cost(shared_paths) <= emitted_cost(independent_paths)
        else independent_paths
    )


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
